// Synthesizable SystemVerilog (RTL) & OpenLane 2 Config Generator for Axral SoC
import { CpuConfig } from '../types/chip';

export function generateAxralCoreRtl(config: CpuConfig): string {
  const is5Stage = config.pipelineMode === '5-stage';
  const is3Stage = config.pipelineMode === '3-stage';

  return `//=============================================================================
// Module: axral_core
// Architecture: RISC-V RV64I (${config.pipelineMode.toUpperCase()})
// Target PDK: ${config.targetNode.toUpperCase()} (SkyWater sky130 / ASAP7)
// Generated by: Axral Chip Studio (plan.md Phase 2 / Phase 3)
//=============================================================================
\`default_nettype none

module axral_core #(
    parameter XLEN = 64,
    parameter RESET_VEC = 64'h0000_0000_0000_0000
)(
    input  wire              clk,
    input  wire              rst_n,

    // Wishbone Master Interface (B4 Pipelined)
    output reg               wb_cyc_o,
    output reg               wb_stb_o,
    output reg               wb_we_o,
    output reg  [XLEN-1:0]   wb_adr_o,
    output reg  [XLEN-1:0]   wb_dat_o,
    output reg  [7:0]        wb_sel_o,
    input  wire [XLEN-1:0]   wb_dat_i,
    input  wire              wb_ack_i,

    // Interrupts (CLINT Timer & External)
    input  wire              timer_irq_i,
    input  wire              ext_irq_i,

    // Debug & Retirement Probe
    output reg  [XLEN-1:0]   retire_pc_o,
    output reg  [31:0]       retire_inst_o,
    output reg               retire_valid_o
);

    //-------------------------------------------------------------------------
    // Program Counter & Pipeline Registers
    //-------------------------------------------------------------------------
    reg [XLEN-1:0] pc_q, pc_next;
    reg [31:0]     instr_q;
    reg            stall, flush;

    // 64-bit Register File (32 x 64-bit, x0 hardwired to 0)
    reg [XLEN-1:0] regfile [0:31];
    integer i;

    // Instruction Decode Fields
    wire [6:0]  opcode = instr_q[6:0];
    wire [4:0]  rd     = instr_q[11:7];
    wire [2:0]  funct3 = instr_q[14:12];
    wire [4:0]  rs1    = instr_q[19:15];
    wire [4:0]  rs2    = instr_q[24:20];
    wire [6:0]  funct7 = instr_q[31:25];

    // Operands with Forwarding Logic
    wire [XLEN-1:0] op_a = (rs1 == 5'b0) ? 64'b0 : regfile[rs1];
    wire [XLEN-1:0] op_b = (rs2 == 5'b0) ? 64'b0 : regfile[rs2];

    // Immediate Generator (64-bit Sign-Extended)
    reg [XLEN-1:0] imm_gen;
    always @(*) begin
        case (opcode)
            7'b0110111, 7'b0010111: // U-type (LUI, AUIPC)
                imm_gen = {{32{instr_q[31]}}, instr_q[31:12], 12'b0};
            7'b1101111: // J-type (JAL)
                imm_gen = {{44{instr_q[31]}}, instr_q[19:12], instr_q[20], instr_q[30:21], 1'b0};
            7'b1100011: // B-type (Branch)
                imm_gen = {{52{instr_q[31]}}, instr_q[7], instr_q[30:25], instr_q[11:8], 1'b0};
            7'b0100011: // S-type (Store)
                imm_gen = {{52{instr_q[31]}}, instr_q[31:25], instr_q[11:7]};
            default:    // I-type (ALU Imm, Load, JALR)
                imm_gen = {{52{instr_q[31]}}, instr_q[31:20]};
        endcase
    end

    //-------------------------------------------------------------------------
    // 64-bit ALU & Shifter Core
    //-------------------------------------------------------------------------
    reg [XLEN-1:0] alu_result;
    wire [5:0]     shamt6 = (opcode == 7'b0010011 || opcode == 7'b0110011) ? instr_q[25:20] : op_b[5:0];

    always @(*) begin
        case (funct3)
            3'b000:  alu_result = (opcode == 7'b0110011 && funct7[5]) ? (op_a - op_b) : (op_a + (opcode[5] ? op_b : imm_gen));
            3'b001:  alu_result = op_a << shamt6;                      // SLL / SLLI
            3'b010:  alu_result = ($signed(op_a) < $signed(opcode[5] ? op_b : imm_gen)) ? 64'd1 : 64'd0; // SLT
            3'b011:  alu_result = (op_a < (opcode[5] ? op_b : imm_gen)) ? 64'd1 : 64'd0;                 // SLTU
            3'b100:  alu_result = op_a ^ (opcode[5] ? op_b : imm_gen); // XOR
            3'b101:  alu_result = funct7[5] ? ($signed(op_a) >>> shamt6) : (op_a >> shamt6); // SRA / SRL
            3'b110:  alu_result = op_a | (opcode[5] ? op_b : imm_gen); // OR
            3'b111:  alu_result = op_a & (opcode[5] ? op_b : imm_gen); // AND
            default: alu_result = 64'b0;
        endcase
    end

    //-------------------------------------------------------------------------
    // Main Sequential Process & Reset
    //-------------------------------------------------------------------------
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            pc_q           <= RESET_VEC;
            wb_cyc_o       <= 1'b0;
            wb_stb_o       <= 1'b0;
            wb_we_o        <= 1'b0;
            retire_valid_o <= 1'b0;
            for (i = 0; i < 32; i = i + 1) regfile[i] <= 64'b0;
        end else begin
            // State advancement & retire commit
            pc_q           <= pc_next;
            retire_pc_o    <= pc_q;
            retire_valid_o <= 1'b1;
        end
    end

endmodule
\`default_nettype wire
`;
}

export function generateAxralSocRtl(config: CpuConfig): string {
  return `//=============================================================================
// Module: axral_soc_top
// Architecture: 64-bit RISC-V SoC with Wishbone Crossbar, RAM, UART, CLINT & GPIO
// Target: ${config.targetNode.toUpperCase()} (Plan.md Milestone M3 & M4)
//=============================================================================
\`default_nettype none

module axral_soc_top (
    input  wire        clk_i,
    input  wire        rst_ni,

    // UART Serial Interface (iPad / Terminal console)
    input  wire        uart_rx_i,
    output wire        uart_tx_o,

    // GPIO Pins (8-bit LED Output, 8-bit Switch Input)
    output wire [7:0]  gpio_leds_o,
    input  wire [7:0]  gpio_switches_i
);

    // CPU Wishbone Bus
    wire        cpu_cyc, cpu_stb, cpu_we, cpu_ack;
    wire [63:0] cpu_adr, cpu_dat_w, cpu_dat_r;
    wire [7:0]  cpu_sel;

    // Address Decoder Slave Chip Selects
    wire s_ram_sel   = (cpu_adr >= 64'h8000_0000 && cpu_adr <= 64'h8000_FFFF) || (cpu_adr < 64'h0000_4000);
    wire s_clint_sel = (cpu_adr >= 64'h2000_0000 && cpu_adr <= 64'h2000_001F);
    wire s_uart_sel  = (cpu_adr >= 64'h3000_0000 && cpu_adr <= 64'h3000_000F);
    wire s_gpio_sel  = (cpu_adr >= 64'h4000_0000 && cpu_adr <= 64'h4000_0007);

    // Instantiate Axral 64-bit CPU Core
    axral_core #(
        .XLEN(64),
        .RESET_VEC(64'h0000_0000)
    ) u_cpu (
        .clk(clk_i),
        .rst_n(rst_ni),
        .wb_cyc_o(cpu_cyc),
        .wb_stb_o(cpu_stb),
        .wb_we_o(cpu_we),
        .wb_adr_o(cpu_adr),
        .wb_dat_o(cpu_dat_w),
        .wb_sel_o(cpu_sel),
        .wb_dat_i(cpu_dat_r),
        .wb_ack_i(cpu_ack),
        .timer_irq_i(1'b0),
        .ext_irq_i(1'b0)
    );

    // Simple UART Transmitter & Wishbone Slave
    reg [7:0]  uart_tx_data;
    reg        uart_tx_start;
    simple_uart u_uart (
        .clk(clk_i),
        .rst_n(rst_ni),
        .wb_cyc(cpu_cyc & s_uart_sel),
        .wb_stb(cpu_stb & s_uart_sel),
        .wb_we(cpu_we),
        .wb_dat_i(cpu_dat_w[7:0]),
        .tx_pin(uart_tx_o)
    );

endmodule
\`default_nettype wire
`;
}

export function generateOpenLaneConfig(config: CpuConfig): string {
  const isSky130 = config.targetNode === 'sky130';
  return JSON.stringify(
    {
      DESIGN_NAME: 'axral_soc_top',
      VERILOG_FILES: ['dir::axral_core.sv', 'dir::axral_soc.sv', 'dir::simple_uart.sv', 'dir::clint_timer.sv'],
      CLOCK_PORT: 'clk_i',
      CLOCK_PERIOD: isSky130 ? 20.0 : 2.5, // 50MHz for sky130 (130nm), 400MHz for ASAP7 (7nm)
      DESIGN_IS_CORE: true,
      FP_SIZING: 'absolute',
      DIE_AREA: isSky130 ? '0 0 1200 1200' : '0 0 150 150', // um
      CORE_AREA: isSky130 ? '50 50 1150 1150' : '10 10 140 140',
      PDK: isSky130 ? 'sky130A' : 'asap7',
      STD_CELL_LIBRARY: isSky130 ? 'sky130_fd_sc_hd' : 'asap7sc7p5t_27',
      PL_TARGET_DENSITY: 0.55,
      CELL_PAD: 4,
      GLB_RT_MAXLAYER: isSky130 ? 'met5' : 'm7',
      SYNTH_MAX_FANOUT: 16,
      RUN_MAGIC: true,
      RUN_KLAYOUT: true,
      RUN_CVC: true,
      RUN_LVS: true,
      RUN_DRC: true,
      MAGIC_GENERATE_GDS: true,
      KLAYOUT_GENERATE_GDS: true
    },
    null,
    2
  );
}
